  "frenzy":{de:"Raserei",desc:"Unkontrollierte, wilde Raserei — kennzeichnet den Moment, in dem ein Turnskin die Kontrolle verliert.",cat:"mind"},
  "friend-of-druids":{de:"Freund der Druiden",desc:"Wachsendes Vertrauen bei den Craggen-Druiden — nötig, um Nochikas Meinung zu gewinnen.",cat:"social"},
