  "gold-sick":{de:"goldkrank",desc:"Von Gier nach Reichtum besessen — trübt das Urteilsvermögen.",cat:"mind"},
  "goldkrank":{de:"goldkrank",desc:"Von Gier nach Reichtum besessen — trübt das Urteilsvermögen.",cat:"mind"},
  "grappled":{de:"gegriffen (Ringkampf)",desc:"Im Nahkampf festgehalten oder umklammert.",cat:"phys"},
  "grazed":{de:"geschürft",desc:"Oberflächliche Schürfwunden durch Reibung oder Anstrengung.",cat:"phys"},
  "greedy":{de:"gierig",desc:"Wachsende, ungesunde Begierde nach Reichtum oder Besitz.",cat:"mind"},
  "green-maiden's-favor":{de:"Wohlwollen der Green Maiden",desc:"Positiver Status, der durch Taten im Sinne der Green Maiden (z. B. Reinigung eines miasma-verderbten Waldgeschöpfs) erworben wird und die spätere Begegnung mit ihr günstiger stimmt.",cat:"pos"},
  "guided-toward":{de:"gelenkt in Richtung",desc:"Eine unsichtbare, wohlwollende Kraft (Gunst des Wasserfall-Schreins) lenkt die Person sacht auf einen zuvor selbstlos ausgesprochenen Wunsch zu — meist durch günstige Zufälle statt direkter Fügung.",cat:"pos"},
  "guilt":{de:"Schuldgefühl (Kurzform)",desc:"Kurzform für ein aufkeimendes Schuldgefühl über vergangenes Handeln.",cat:"mind"},
  "guilty":{de:"schuldbewusst",desc:"Von Schuldgefühlen geplagt.",cat:"mind"},
  "harrowed":{de:"gepeinigt",desc:"Emotional erschüttert nach einem beunruhigenden Erlebnis wie einem heimsuchenden Albtraum.",cat:"mind"},
  "haughty":{de:"hochmütig",desc:"Blickt aufgrund von Wohlstand oder Status auf andere herab.",cat:"social"},
