  "heimvorteil":{de:"Heimvorteil",desc:"Vertrautheit mit der eigenen Umgebung verschafft einen taktischen Vorteil.",cat:"pos"},
  "heimwehkrank":{de:"heimwehkrank",desc:"Sehnsucht nach der Heimat schwächt Entschlossenheit und Konzentration.",cat:"mind"},
  "hidden":{de:"verborgen",desc:"Nicht sichtbar oder auffindbar.",cat:"pos"},
  "hiding-intentions":{de:"Absichten verbergend",desc:"Verschleiert die eigenen wahren Ziele hinter einer Fassade — narrativer Täuschungs-Tag, kein spürbarer Zustand für Außenstehende.",cat:"narrative"},
  "high":{de:"hoch angebracht",desc:"Ortsbeschreibung, z. B. eine gut sichtbare, erhöhte Position — kein klassischer Status, sondern ein Hinweis auf den Fundort.",cat:"narrative"},
  "home-advantage":{de:"Heimvorteil",desc:"Vertrautheit mit der eigenen Umgebung verschafft einen taktischen Vorteil.",cat:"pos"},
