  "hostile":{de:"feindselig",desc:"Offen ablehnend und auf Konfrontation aus.",cat:"social"},
  "hungrig":{de:"hungrig",desc:"Fehlende Nahrung schwächt zunehmend Kraft und Konzentration.",cat:"phys"},
