  "itchy":{de:"juckend (Variante)",desc:"Hautreizung durch Bisse oder Stiche — inhaltsgleich mit 'itching'.",cat:"phys"},
  "jovial":{de:"ausgelassen",desc:"Gespielt fröhlich — kann bei NPCs auch als Tarnung für etwas anderes dienen.",cat:"pos"},
  "juckend":{de:"juckend",desc:"Ein lästiger Juckreiz lenkt ab und stört die Konzentration.",cat:"phys"},
  "judgmental":{de:"verurteilend",desc:"Neigt zu vorschnellem, hartem Urteil über andere.",cat:"mind"},
  "kalt":{de:"kalt",desc:"Kälte setzt dem Körper zu — mit der Zeit gefährlich, wenn nicht gelindert.",cat:"phys"},
  "kalte":{de:"kalt",desc:"Kälte setzt dem Körper zu — mit der Zeit gefährlich, wenn nicht gelindert.",cat:"phys"},
