  "laborers":{de:"Arbeiter (Kurzform)",desc:"Kurzform-Fragment von friend-of-laborers — siehe dort.",cat:"social"},
  "light-hearted":{de:"leichtherzig",desc:"Positive, unbeschwerte Gemütslage — kann als Verlust markiert werden, wenn ein Schatten sie 'mitnimmt'.",cat:"pos"},
  "light-weight":{de:"leichtfüßig",desc:"Bewegt sich ungewöhnlich leicht, fast schwerelos.",cat:"pos"},
