  "loyal":{de:"loyal",desc:"Treu ergeben, handelt aus echter Überzeugung statt aus Zwang — Gegenstück zu 'bullied'.",cat:"pos"},
  "magical-fire":{de:"magisches Feuer",desc:"Von magischem Feuer erfasst — verhält sich anders als gewöhnliches Feuer und ist schwerer zu löschen.",cat:"magic"},
