  "nachdenklich":{de:"nachdenklich",desc:"Ein Moment des Innehaltens und Nachsinnens über das eigene Leben oder die Welt.",cat:"mind"},
  "nass":{de:"nass",desc:"Durchnässte Kleidung und Ausrüstung — unangenehm und potenziell schwächend bei Kälte.",cat:"phys"},
  "nausea":{de:"übel",desc:"Starkes Unwohlsein, oft kurz vor dem Erbrechen.",cat:"phys"},
