  "offering":{de:"Opfergabe",desc:"Markiert eine erfolgreich dargebrachte Opfergabe — bei der Green Maiden Voraussetzung, um MAKE OFFERING zu füllen.",cat:"narrative"},
  "on-edge":{de:"angespannt",desc:"Die Nerven liegen blank — Unruhe und Reizbarkeit erschweren besonnenes Handeln.",cat:"mind"},
  "ouch":{de:"schmerzhaft getroffen",desc:"Leichter, aber spürbarer Schmerz durch Kratzer, Bisse oder Tritte.",cat:"phys"},
