  "peaceful":{de:"friedvoll",desc:"Innerlich ruhig und im Reinen — ein positiver Status.",cat:"pos"},
  "pech":{de:"Pech (verhext)",desc:"Ein Hexenspruch bringt anhaltendes Unglück über sein Opfer.",cat:"magic"},
  "penniless":{de:"mittellos",desc:"Wurde all seiner Wertsachen oder seines Geldes beraubt.",cat:"narrative"},
  "petrified":{de:"starr vor Angst",desc:"Wie erstarrt — kann sich vorerst nicht bewegen oder reagieren, bis sie/er aus der Starre gerissen wird.",cat:"mind"},
