// Kurzhinweise, wie man einen Status typischerweise senkt/loswird — nach
// Kategorie, damit nicht 105x derselbe Textbaustein gepflegt werden muss.
const REDUCE_HINTS = {
  phys:"Senken: meist durch Erste Hilfe, Heilkunst oder eine Rast — kostet die passende Aktion 1 Power pro Stufe.",
  mind:"Senken: meist durch Trost, ein gutes Gespräch, einen Erfolg oder Zeit — kostet die passende Aktion 1 Power pro Stufe.",
  social:"Senken: meist durch überzeugendes Handeln, eine gute Tat oder Zeit — kostet die passende Aktion 1 Power pro Stufe.",
  magic:"Senken: braucht meist ein Gegenmittel, eine Reinigung oder passende Magie — kostet die passende Aktion 1 Power pro Stufe.",
  env:"Betrifft die Szene/Umgebung, nicht direkt eine Person — verschwindet meist, wenn die Ursache behoben ist (z. B. Feuer gelöscht).",
  pos:"Ein positiver Status — muss nicht gesenkt werden. Klingt von selbst ab, wenn er erzählerisch keinen Sinn mehr ergibt.",
  narrative:"Kein persönlicher Zustand, sondern ein situativer Tag — verschwindet, sobald er erzählerisch keinen Sinn mehr ergibt.",
};

// Erkennt "wort-N" bzw. "wort-teil-N"-Muster in bereits gerenderten HTML-Strings
// und macht bekannte Status-Begriffe anklickbar + zeigt die deutsche Übersetzung.
// Unbekannte Begriffe (noch nicht im Wörterbuch) bleiben unverändert stehen.
// Sammelt bereits gemeldete unbekannte Status-Begriffe, damit das Konsolen-
// Logging bei wiederholten render()-Durchläufen (z. B. nach jedem Limit-Pip-
// Klick) nicht denselben fehlenden Begriff dutzendfach ausgibt — jeder
// Begriff wird nur beim ersten Auftreten pro Sitzung gemeldet.
const _warnedMissingStatuses = new Set();
function linkStatuses(html){
  if(!html) return html;
  return html.replace(/(?<![a-zA-ZäöüßÄÖÜ'])([a-zA-ZäöüßÄÖÜ][a-zA-ZäöüßÄÖÜ']*(?:-[a-zA-ZäöüßÄÖÜ']+)*)-(\d+)(?![a-zA-Z0-9])/g, (match, base, tier)=>{
    const key = base.toLowerCase();
    const s = STATUS_TERMS[key];
    if(!s){
      if(!_warnedMissingStatuses.has(key)){
        _warnedMissingStatuses.add(key);
        console.warn(`[STATUS_TERMS] Unbekannter Status-Begriff "${key}" (erkannt aus "${match}") ist nicht in STATUS_TERMS hinterlegt — bitte ergänzen (de/desc/cat).`);
      }
      return match;
    }
    return `<span class="gloss status-gloss" onclick="event.stopPropagation(); openStatus('${key}','${tier}')">${s.de}-${tier}</span>`;
  });
}


function openStatus(key, tier){
  const s = STATUS_TERMS[key];
  if(!s) return;
  currentGlossId = null; // Status-Begriffe sind keine GLOSSARY-Einträge, daher kein Favoriten-Stern
  document.getElementById("glossModalInner").classList.remove("rest-modal");
  document.getElementById("glossPortrait").innerHTML = "";
  document.getElementById("glossEyebrow").textContent = "Status" + (tier ? " · Stufe " + tier : "");
  document.getElementById("glossTitle").textContent = s.de + (tier ? "-" + tier : "");
  const hint = REDUCE_HINTS[s.cat] || "";
  document.getElementById("glossBody").innerHTML =
    `<p>${s.desc}</p>${hint?`<p>${hint}</p>`:''}<p style="opacity:.6; font-size:12.5px;">Original im Buch: <strong>${key}${tier?'-'+tier:''}</strong></p>`;
  updateGlossFavBtn();
  document.getElementById("glossModal").classList.add("open");
}

// Merkt sich, ob der aktuell offene Glossareintrag über die Orte- oder
// NPC-Bibliothek geöffnet wurde (siehe jumpToPlace/jumpToCharacter)
// — falls ja, führt das Schließen des Glossars zurück zum jeweiligen
// Bibliotheks-Fenster statt alles zu schließen. Wird von jedem "normalen"
// openGloss()-Aufruf (z. B. über einen .gloss-Link im Fließtext) wieder
// zurückgesetzt.
let glossOrigin = null;
function openGloss(id){
  const g = GLOSSARY[id];
  if(!g) return;
  glossOrigin = null;
  currentGlossId = id;
  const modalInner = document.getElementById("glossModalInner");
  modalInner.classList.toggle("rest-modal", !!g.wide);
  document.getElementById("glossPortrait").innerHTML = portraitHtml(g.img, "gm-portrait-img");
  document.getElementById("glossEyebrow").textContent = g.page;
  document.getElementById("glossTitle").textContent = g.term;
  document.getElementById("glossBody").innerHTML = g.wide
    ? `<div class="flow">${g.body.join("")}</div>`
    : g.body.map(p=>`<p>${p}</p>`).join("");
  updateGlossFavBtn();
  document.getElementById("glossModal").classList.add("open");
}
function closeGloss(){
  document.getElementById("glossModal").classList.remove("open");
  if(glossOrigin === "places"){
    glossOrigin = null;
    openPlaces();
  } else if(glossOrigin === "characters"){
    glossOrigin = null;
    openCharacters();
  }
}
document.addEventListener("keydown", (e)=>{
  if(e.key!=="Escape") return;
  // Vor dem Schließen merken, ob überhaupt ein Fenster offen war — nur
  // dann soll Escape "nur" das Fenster schließen. War keins offen, macht
  // Escape stattdessen etwas anderes (Notizfeld zuklappen oder zurück zur
  // Übersicht, siehe unten).
  const anyModalWasOpen = !!document.querySelector(".gloss-modal-backdrop.open");
  closeMap();
  closeRulesGloss();
  closeGrimoire();
  closeThemebook();
  closeSearch();
  closeChallenges();
  closeLore();
  closeDice();
  closePlaces();
  closeCharacters();
  closeFavorites();
  closeTopbarSettings();
  closeTopbarMenu();
  // closeGloss() zuletzt: War der Glossareintrag über die Orte- oder
  // NPC-Bibliothek geöffnet (jumpToPlace/jumpToCharacter), öffnet es
  // sie wieder — das darf nicht durch die vorherigen closePlaces()/
  // closeCharacters()-Aufrufe sofort rückgängig gemacht werden.
  closeGloss();
  // Profile-Modal: Bei offener Detail-Ansicht führt Escape zuerst eine
  // Ebene zurück zur Profil-Übersicht; erst ein zweites Escape schließt
  // das Fenster komplett.
  const profilesOpen = document.getElementById("profilesModal").classList.contains("open");
  if(profilesOpen && profilesState.view==="detail"){
    backToProfileList();
  } else {
    closeProfiles();
  }
  if(anyModalWasOpen) return;

  // Kein Fenster war offen: Im Notizfeld blendet Escape nur das Feld
  // wieder aus (statt die Seite zu verlassen); ansonsten springt Escape
  // innerhalb eines Abenteuers zurück zur Gesamtübersicht (neu, Juli 2026).
  const active = document.activeElement;
  if(active && active.classList && active.classList.contains("adv-notes-textarea")){
    const details = active.closest(".adv-notes");
    if(details){
      details.open = false;
      if(state.advId) state.notesOpen[state.advId] = false;
    }
    active.blur();
    return;
  }
  if(state.view==="adventure"){
    goOverview();
  }
});

// Dauerhaft über den Rasten-Button erreichbar — für den Moment, in dem die
// Gruppe am Tisch sagt "wir lagern hier" oder eine längere Pause einlegt.
function openRestRules(){
  document.getElementById("glossModalInner").classList.add("rest-modal");
  document.getElementById("glossPortrait").innerHTML = "";
  document.getElementById("glossEyebrow").textContent = "Spielregeln, Abschnitt 20";
  document.getElementById("glossTitle").textContent = "Camping & Sojourns";
  document.getElementById("glossBody").innerHTML = `
    <div class="flow">
    <p>Hält die Fellowship zwischen Szenen an, um Kräfte zu sammeln, pausiert der Szenenfluss — das ist eine <strong>Camping</strong>-Szene. Bei einem längeren Aufenthalt (Tage, Wochen, Monate) spricht man von einem <strong>Sojourn</strong>.</p>
    <span class="section-heading">Vorbereitung</span>
    <p>Die Gruppe muss zuerst einen geeigneten Ort finden. Du kannst dem Ort Story Tags/Statuses geben (z. B. <em>beautiful vista, annoying gnats</em>) und optional einen Threat setzen.</p>
    <span class="section-heading">Ablauf — zwei Perioden</span>
    <p>Gespielt werden zwei Perioden (erste/zweite Wache, oder erste/zweite Hälfte des Aufenthalts). Jede Person wählt pro Periode <strong>eine</strong> Aktivität — REST und REFLECT je nur einmal pro Szene, eine CAMP ACTION beliebig oft:</p>
    <div class="rest-activities">
      <div class="rest-activity">
        <span class="ra-title">💤 Rest</span>
        <p>Statuses ablaufen lassen. <strong>Camp:</strong> einige Statuses (ggf. negative Story Tags) ablaufen lassen und Power-Tags wiederherstellen, die sich durch Ruhe erholen würden. <strong>Sojourn:</strong> auch schwerere Verletzungen, Krankheiten oder Erschöpfung können ablaufen.</p>
      </div>
      <div class="rest-activity">
        <span class="ra-title">🕯 Reflect</span>
        <p>Improve markieren. <strong>Camp:</strong> Improve auf einem eigenen Theme oder dem Fellowship-Theme. <strong>Sojourn:</strong> eine echte Improvement. Guter Moment, um Abandon/Milestone auf einem Quest zu reflektieren.</p>
      </div>
      <div class="rest-activity">
        <span class="ra-title">🪵 Camp Action</span>
        <p>Z. B. Wunden versorgen, reden, kochen, jagen/sammeln, Wache halten, recherchieren, vorauskundschaften. Power zählt wie in einer normalen Szene; bei 1+ Power kann die Hälfte (aufgerundet) direkt ohne Würfeln eingesetzt werden. <strong>Sojourn:</strong> zusätzliches Power (+1 Tage, +2 Wochen, +3 Monate).</p>
      </div>
    </div>
    <span class="callout"><span class="co-title">Dritte Aktivität</span>Eine dritte Aktivität ist möglich, auf Kosten von Consequences — sie findet in einer dritten Periode statt, an der nur die beteiligten Personen teilnehmen.</span>
    <span class="section-heading">Fellowship Quality Time</span>
    <p>Vor Ende der Rast: Jede Person kann entweder einen Fellowship-Theme-Tag wiederherstellen oder eine neue Beziehung zu einer Person erschaffen, mit der noch keine besteht.</p>
    <span class="section-heading">Danach</span>
    <p>Die Geschichte geht weiter, eine neue Szene beginnt.</p>
    </div>
  `;
  document.getElementById("glossModal").classList.add("open");
}
